declare(strict_types=1);require_once __DIR__.'/auth.php';$user=require_role('supervisor');$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT);$errors=[];
if(!$id){http_response_code(404);exit('Mantención no encontrada.');}$stmt=db()->prepare('SELECT m.*,c.codigo FROM mantenciones m JOIN carros c ON c.id=m.carro_id WHERE m.id=?');$stmt->execute([$id]);$m=$stmt->fetch();if(!$m){http_response_code(404);exit('Mantención no encontrada.');}$tipo=(string)$m['tipo'];$descripcion=(string)$m['descripcion'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf_token']??null))$errors[]='La sesión expiró. Recarga la página.';$tipo=(string)($_POST['tipo']??'');$descripcion=trim((string)($_POST['descripcion']??''));if(!in_array($tipo,['Preventiva','Correctiva'],true))$errors[]='Tipo inválido.';if($descripcion===''||mb_strlen($descripcion)>10000)$errors[]='La descripción es obligatoria.';$new=null;$file=$_FILES['foto']??null;if($file&&$file['error']!==UPLOAD_ERR_NO_FILE){if($file['error']!==UPLOAD_ERR_OK||$file['size']>MAX_UPLOAD_BYTES)$errors[]='La foto es inválida o supera los 5 MB.';else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime])||!@getimagesize($file['tmp_name']))$errors[]='Solo se permiten imágenes JPG, PNG o WEBP.';else{$new=bin2hex(random_bytes(20)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],__DIR__.'/uploads/'.$new)){$errors[]='No se pudo guardar la foto.';$new=null;}}}}if(!$errors){$photo=$new?:$m['foto'];db()->prepare('UPDATE mantenciones SET tipo=?,descripcion=?,foto=? WHERE id=?')->execute([$tipo,$descripcion,$photo,$id]);if($new&&$m['foto']&&preg_match('/^[a-f0-9]{40}\.(jpg|png|webp)$/',$m['foto']))@unlink(__DIR__.'/uploads/'.$m['foto']);redirect('historial.php?carro='.rawurlencode($m['codigo']));}if($new)@unlink(__DIR__.'/uploads/'.$new);}
require_once __DIR__.'/partials/layout.php';layout_start('Editar mantención',$user,'historial');?><a class="module-back" href="historial.php?carro=<?=rawurlencode($m['codigo'])?>">← Volver al historial</a><section class="module-card"><h1>Editar mantención</h1><p>Carro: <strong><?=e($m['codigo'])?></strong></p><?php if($errors): ?><div class="module-alert error"><ul><?php foreach($errors as $error): ?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><label for="tipo">Tipo</label><select id="tipo" name="tipo"><option <?=$tipo==='Preventiva'?'selected':''?>>Preventiva</option><option <?=$tipo==='Correctiva'?'selected':''?>>Correctiva</option></select><label for="descripcion">Descripción</label><textarea id="descripcion" name="descripcion" maxlength="10000" required><?=e($descripcion)?></textarea><label for="foto">Reemplazar foto (opcional)</label><input id="foto" type="file" name="foto" accept="image/jpeg,image/png,image/webp" capture="environment"><button type="submit">Guardar cambios</button></form></section><?php layout_end();
